using Microsoft.AspNetCore.Antiforgery;
using Microsoft.EntityFrameworkCore;
namespace Osynix.Ats.Services;
public record InterviewProposalReview(Guid SubmissionId,Guid InterviewId,Guid Revision,bool Accept,string? LocalStart,string TimeZone);
public static class InterviewEndpoints {
 static void Private(HttpContext c){c.Response.Headers.CacheControl="no-store";c.Response.Headers["Referrer-Policy"]="no-referrer";c.Response.Headers["X-Content-Type-Options"]="nosniff";c.Response.Headers["X-Robots-Tag"]="noindex, nofollow";c.Response.Headers["Content-Security-Policy"]="frame-ancestors 'self'";}
 public static void MapInterviews(this WebApplication app){
  app.MapGet("/interview/access",async Task<IResult>(string? token,InterviewService service,HttpContext c)=>{Private(c);var result=await service.Exchange(token??"");if(result is null)return Results.Redirect("/interview?expired=true");c.Response.Cookies.Append(InterviewService.CookieName,result.Value.Cookie,new(){HttpOnly=true,Secure=c.Request.IsHttps,SameSite=SameSiteMode.Strict,Path="/interview",Expires=new DateTimeOffset(result.Value.Expires,TimeSpan.Zero)});return Results.Redirect("/interview");}).AllowAnonymous().RequireRateLimiting("review");
  app.MapGet("/interview/data",async Task<IResult>(InterviewService service,HttpContext c)=>{Private(c);try{return Results.Json(await service.Read(c.Request.Cookies[InterviewService.CookieName]));}catch(UnauthorizedAccessException){return Results.Unauthorized();}}).AllowAnonymous().RequireRateLimiting("review");
  app.MapPost("/interview/respond",async Task<IResult>(InterviewResponse input,InterviewService service,IAntiforgery csrf,HttpContext c)=>{Private(c);try{await csrf.ValidateRequestAsync(c);await service.Respond(c.Request.Cookies[InterviewService.CookieName],input);return Results.Ok(new{message="Response Saved. Your Recruiter And Hiring Manager Have Been Updated."});}catch(AntiforgeryValidationException){return Results.BadRequest(new{message="Refresh This Page Before Responding."});}catch(UnauthorizedAccessException){return Results.Unauthorized();}catch(DbUpdateConcurrencyException){return Results.Conflict(new{message="This Interview Changed. Refresh Before Responding."});}catch(InvalidOperationException e){return Results.BadRequest(new{message=e.Message});}}).AllowAnonymous().RequireRateLimiting("review");
  app.MapPost("/review/interview",async Task<IResult>(InterviewProposalReview input,HiringReviewService review,InterviewService service,IAntiforgery csrf,HttpContext c)=>{Private(c);try{await csrf.ValidateRequestAsync(c);var appId=await review.SharedApplication(c.Request.Cookies[HiringReviewService.CookieName],input.SubmissionId);await service.ReviewProposal(appId,input.InterviewId,input.Revision,input.Accept,input.LocalStart,input.TimeZone);return Results.Ok(new{message="Interview Updated. Candidate Notification Prepared."});}catch(AntiforgeryValidationException){return Results.BadRequest(new{message="Refresh This Page Before Responding."});}catch(UnauthorizedAccessException){return Results.Unauthorized();}catch(DbUpdateConcurrencyException){return Results.Conflict(new{message="This Interview Changed. Refresh Before Responding."});}catch(InvalidOperationException e){return Results.BadRequest(new{message=e.Message});}}).AllowAnonymous().RequireRateLimiting("review");
 }
}
